function createWsServer(url, isSsoAuth = false) {
  const wssServer = new WebSocket.Server({ serverEventEmitter: wssServer, port: 80, ws: true });
  const connector = wssServer.createConnector({ url: url, ssl: true }, isSsoAuth);

  return { websocket: connector };
}
